    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.deposit{value: 1 wei}();
        uint balanceBefore = address(c).balance;
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        uint balanceAfter = address(c).balance;
        assertTrue(success == true && balanceAfter == 0);
    }
}
